  const expectedFee = Math.round(expectedPercentage * daysOverdue);
  assert.equal(fee, expectedFee);
});

test('lateFee increases with more days overdue', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET30');
