test('vatSummary includes paid invoices', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const totals = invoiceTotals(invoice);
  const paid = recordPayment(invoice, { amount: totals.total, date: '2026-10-20' });
  assert.equal(paid.ok, true);
  assert.equal(paid.value.status, 'paid');
  const result = vatSummary([paid.value]);
  assert.equal(result.length, 1);
  assert(result[0].base > 0);
  assert(result[0].vat > 0);
});

test('vatSummary aggregates multiple invoices with same VAT rate', () => {
  const invoice1 = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const invoice2 = issueTestInvoice('C-002', '2026-10-05', 'NET30');
  const result = vatSummary([invoice1, invoice2]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert(result[0].base > 0);
  assert(result[0].vat > 0);
});

test('vatSummary separates invoices by VAT rate', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result1.ok, true);
  const issued1 = issueInvoice(result1.value, []);
  assert.equal(issued1.ok, true);

  const result2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'PRINT-A4', qty: 2 }],
  });
  assert.equal(result2.ok, true);
  const issued2 = issueInvoice(result2.value, []);
  assert.equal(issued2.ok, true);

  const result = vatSummary([issued1.value, issued2.value]);
  assert.equal(result.length, 2);
  for (const entry of result) {
    assert.equal(typeof entry.rate, 'number');
    assert.equal(typeof entry.base, 'number');
    assert.equal(typeof entry.vat, 'number');
  }
});

test('vatSummary sorts by rate high to low', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result1.ok, true);
  const issued1 = issueInvoice(result1.value, []);
  assert.equal(issued1.ok, true);

  const result2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'PRINT-A4', qty: 2 }],
  });
  assert.equal(result2.ok, true);
  const issued2 = issueInvoice(result2.value, []);
  assert.equal(issued2.ok, true);

  const result = vatSummary([issued2.value, issued1.value]);
  assert.equal(result.length, 2);
  assert.equal(result[0].rate, 21);
  assert.equal(result[1].rate, 9);
});

test('vatSummary calculates base as lineTotal minus lineDiscount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);
  const summary = vatSummary([issued.value]);
  assert.equal(summary.length, 1);
  assert(summary[0].base > 0);
