    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);
  const summary = vatSummary([issued.value]);
  assert.equal(summary.length, 1);
  assert(summary[0].base > 0);
});

test('vatSummary handles invoices with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });
  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);
  const summary = vatSummary([issued.value]);
  assert.equal(summary.length, 1);
  assert(summary[0].base > 0);
  assert(summary[0].vat > 0);
});

test('vatSummary includes VAT rate 0 when present', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });
  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);
  const summary = vatSummary([issued.value]);
  assert.equal(summary.length, 1);
  assert.equal(summary[0].rate, 0);
  assert.equal(summary[0].vat, 0);
  assert(summary[0].base > 0);
});

test('vatSummary includes VAT rate 9 when present', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'PRINT-A4', qty: 2 }],
  });
  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);
  const summary = vatSummary([issued.value]);
  assert.equal(summary.length, 1);
  assert.equal(summary[0].rate, 9);
  assert(summary[0].vat > 0);
});

test('vatSummary aggregates lines from multiple invoices with same rate', () => {
  const invoice1 = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const invoice2 = issueTestInvoice('C-002', '2026-10-05', 'NET30');
  const summary = vatSummary([invoice1, invoice2]);
  assert.equal(summary.length, 1);
  assert.equal(summary[0].rate, 21);
});

test('vatSummary with partial payment does not affect base and vat', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const totals = invoiceTotals(invoice);
  const paid = recordPayment(invoice, { amount: totals.total / 2, date: '2026-10-20' });
  assert.equal(paid.ok, true);

  const summary1 = vatSummary([invoice]);
  const summary2 = vatSummary([paid.value]);
  assert.deepEqual(summary1, summary2);
});

test('vatSummary with discount reduces base but not vat rate', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 20 }],
  });
  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);
  const summary = vatSummary([issued.value]);
  assert.equal(summary.length, 1);
  assert.equal(summary[0].rate, 21);
  assert(summary[0].base > 0);
});

test('lateFee returns 0 when invoice is not overdue', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  // Due: 2026-10-31
  const fee = lateFee(invoice, '2026-10-31');
  assert.equal(fee, 0);
});

test('lateFee returns 0 when asOf equals dueDate', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const fee = lateFee(invoice, '2026-10-31');
  assert.equal(fee, 0);
});

test('lateFee returns 0 when asOf is before dueDate', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const fee = lateFee(invoice, '2026-10-30');
  assert.equal(fee, 0);
});

test('lateFee calculates fee for 1 day overdue', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const totals = invoiceTotals(invoice);
  // Due: 2026-10-31, 1 day overdue on 2026-11-01
  const fee = lateFee(invoice, '2026-11-01');
  const expected = Math.round(totals.total * 0.04 / 100 * 1);
  assert.equal(fee, expected);
});

test('lateFee calculates fee for multiple days overdue', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const totals = invoiceTotals(invoice);
  // Due: 2026-10-31, 10 days overdue on 2026-11-10
  const fee = lateFee(invoice, '2026-11-10');
  const expected = Math.round(totals.total * 0.04 / 100 * 10);
  assert.equal(fee, expected);
});

test('lateFee with partial payment reduces due amount', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const totals = invoiceTotals(invoice);
  const paid = recordPayment(invoice, { amount: totals.total / 2, date: '2026-10-20' });
  assert.equal(paid.ok, true);
  // Due: 2026-10-31, 10 days overdue on 2026-11-10
  const fee = lateFee(paid.value, '2026-11-10');
  const expectedFee = Math.round((totals.total / 2) * 0.04 / 100 * 10);
  assert.equal(fee, expectedFee);
});

test('lateFee returns 0 for fully paid invoice', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const totals = invoiceTotals(invoice);
  const paid = recordPayment(invoice, { amount: totals.total, date: '2026-10-20' });
  assert.equal(paid.ok, true);
  const fee = lateFee(paid.value, '2026-11-10');
  assert.equal(fee, 0);
});

test('lateFee calculates fee even for draft invoice (uses calculated dueDate)', () => {
  const invoice = createTestInvoice('C-001', '2026-10-01', 'NET30');
  const fee = lateFee(invoice, '2026-11-10');
  assert(fee > 0);
});

test('lateFee 0.04% calculation is accurate', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const totals = invoiceTotals(invoice);
  const daysOverdue = 5;
  const fee = lateFee(invoice, '2026-11-05');
  const expectedPercentage = totals.total * 0.04 / 100;
  const expectedFee = Math.round(expectedPercentage * daysOverdue);
  assert.equal(fee, expectedFee);
});

test('lateFee increases with more days overdue', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const fee1 = lateFee(invoice, '2026-11-01');
  const fee5 = lateFee(invoice, '2026-11-05');
  const fee10 = lateFee(invoice, '2026-11-10');
  assert(fee1 > 0);
  assert(fee5 > fee1);
  assert(fee10 > fee5);
});

test('lateFee scales linearly with due amount', () => {
  const invoice1 = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const totals1 = invoiceTotals(invoice1);

  const result2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(result2.ok, true);
  const invoice2 = issueInvoice(result2.value, []);
  assert.equal(invoice2.ok, true);
  const totals2 = invoiceTotals(invoice2.value);

  const fee1 = lateFee(invoice1, '2026-11-10');
  const fee2 = lateFee(invoice2.value, '2026-11-10');

  const ratio = totals2.total / totals1.total;
  assert.equal(Math.round(fee2 / ratio), fee1);
});

test('lateFee handles large amounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'LOGO-PACK', qty: 10 }],
  });
  assert.equal(result.ok, true);
  const invoice = issueInvoice(result.value, []);
  assert.equal(invoice.ok, true);
  const fee = lateFee(invoice.value, '2026-11-10');
  assert(fee > 0);
});

test('lateFee rounds correctly to whole cents', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const fee = lateFee(invoice, '2026-11-02');
  assert.equal(fee, Math.round(fee));
});

test('lateFee with NET14 terms', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET14');
  const totals = invoiceTotals(invoice);
  // Due: 2026-10-15, 10 days overdue on 2026-10-25
  const fee = lateFee(invoice, '2026-10-25');
  const expected = Math.round(totals.total * 0.04 / 100 * 10);
  assert.equal(fee, expected);
});

test('lateFee with EOM terms', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-15', 'EOM');
  const totals = invoiceTotals(invoice);
  // Due: 2026-10-31, 5 days overdue on 2026-11-05
  const fee = lateFee(invoice, '2026-11-05');
  const expected = Math.round(totals.total * 0.04 / 100 * 5);
  assert.equal(fee, expected);
});

test('lateFee does not mutate the invoice', () => {
  const invoice = issueTestInvoice('C-001', '2026-10-01', 'NET30');
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));
  lateFee(invoice, '2026-11-10');
  assert.deepEqual(invoice, invoiceCopy);
});

