node -e "
import { dashboard } from './src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals } from './src/invoices.js';
import { recordPayment } from './src/payments.js';

// Create sample invoices
const draft = createInvoice({
  customerId: 'C-001',
  issueDate: '2026-10-01',
  lines: [{ sku: 'DES-HOUR', qty: 5 }],
}).value;

const inv1 = issueInvoice(createInvoice({
  customerId: 'C-001',
  issueDate: '2026-10-01',
  lines: [{ sku: 'DES-HOUR', qty: 5 }],
}).value, []).value;

const inv2 = issueInvoice(createInvoice({
  customerId: 'C-002',
  issueDate: '2026-10-05',
  lines: [{ sku: 'LOGO-PACK', qty: 1 }],
}).value, []).value;

const inv3 = issueInvoice(createInvoice({
  customerId: 'C-003',
  issueDate: '2026-10-01',
  lines: [{ sku: 'DES-HOUR', qty: 10 }],
}).value, []).value;

const paid = issueInvoice(createInvoice({
  customerId: 'C-004',
  issueDate: '2026-09-01',
  lines: [{ sku: 'LOGO-PACK', qty: 2 }],
}).value, []).value;
const totals = invoiceTotals(paid);
const paidInv = recordPayment(paid, { amount: totals.total, date: '2026-10-15' }).value;

const result = dashboard([draft, inv1, inv2, inv3, paidInv], '2026-11-01');

console.log('Dashboard Report');
console.log('================');
console.log('Invoice Counts:');
console.log('  Draft:', result.counts.draft);
console.log('  Issued:', result.counts.issued);
console.log('  Partially Paid:', result.counts.partially_paid);
console.log('  Paid:', result.counts.paid);
console.log('');
console.log('Outstanding Total: €' + (result.outstanding / 100).toFixed(2));
console.log('');
console.log('Overdue:');
console.log('  Count:', result.overdue.count);
console.log('  Amount: €' + (result.overdue.amount / 100).toFixed(2));
console.log('');
console.log('Top Customers:');
result.topCustomers.forEach((c, i) => {
  console.log('  ' + (i + 1) + '. ' + c.customerId + ' - €' + (c.due / 100).toFixed(2));
});
"

